/bin/bash -lc "cat > inspect_candidate.py <<'PY'
import gzip, collections, sys
cand='AACATGGAGCGCCGGG-1'
exclude={'chrM','chrX','chrY','M','X','Y'}; max_w=1000
last_chr=None; d=collections.defaultdict(list)
chroms=[]
with gzip.open('atac.doublet.q1.bed.gz','rt') as f:
 for line in f:
  p=line.split(); ch=p[0]; s=int(p[1]); e=int(p[2]); bc=p[3]
  if ch "'!= last_chr:
   if last_chr and last_chr not in exclude:
    pass
   last_chr=ch
  if ch in exclude or e-s>max_w or bc!=cand: continue
  d[ch].append((s,e))
print('"'chroms', len(d), 'total frags', sum(len(v) for v in d.values()))
for ch, ints in d.items():
 events=collections.defaultdict(int)
 for s,e in ints:
  events[s]+=1; events[e]-=1
 cov=0; regions=[]; start=None
 # need output regions where cov>=3; easiest sweep positions and mark
 for pos in sorted(events):
  old=cov; cov+=events[pos]
  if old<3 and cov>=3:
   start=pos
  elif old>=3 and cov<3:
   regions.append((start,pos))
 print(ch, len(regions))
 for r in regions[:20]: print(' ',r)
 if len(regions)>20: print(' ...')
PY"

